<template><form class="customer-form" @submit.prevent="submit"><div class="form-grid"><label>{{ t('company') }} <span>*</span><input v-model.trim="form.name" required maxlength="255" placeholder="Acme Corporation" /></label><label>{{ t('email') }}<input v-model.trim="form.email" type="email" placeholder="hello@company.com" /></label><label>{{ t('industry') }}<input v-model.trim="form.industry" maxlength="100" placeholder="Technology" /></label><label>{{ t('phone') || 'Телефон' }}<input v-model.trim="form.phone" minlength="5" maxlength="20" placeholder="+380 00 000 00 00" /></label><label class="wide">{{ t('address') }}<input v-model.trim="form.address" placeholder="Company address" /></label></div><p v-if="error" class="form-error">{{ error }}</p><div class="form-actions"><button type="button" class="ghost-btn" @click="$emit('cancel')">{{ t('cancel') }}</button><button class="primary-btn compact" :disabled="saving">{{ saving ? '…' : submitLabel }} <span>→</span></button></div></form></template>
<script setup>
import { reactive, watch } from 'vue'; import { t } from '../../i18n'
const props = defineProps({ customer: { type: Object, default: null }, saving: Boolean, error: String, submitLabel: { type: String, default: 'Save customer' } })
const emit = defineEmits(['submit','cancel']); const form = reactive({ name:'', email:'', industry:'', phone:'', address:'' })
watch(() => props.customer, value => Object.assign(form, { name:value?.name || '', email:value?.email || '', industry:value?.industry || '', phone:value?.phone || '', address:value?.address || '' }), { immediate:true })
function submit(){ emit('submit', { ...form, email: form.email || null, industry: form.industry || null, phone: form.phone || null, address: form.address || null }) }
</script>
